// MARK: - Exception Handling
fileprivate func lava_throwException(buffer: FlatBuffer) -> any Error {
  guard let data = buffer.constData else {
    return RuntimeError(message: "Failed to read exception data")
  }
  let exId = data.load(fromByteOffset: 16, as: UInt32.self)
  switch exId {
  case 0:
    return unmarshal_FontNotFound(buffer: data, offset: 16)
  case 1:
    return unmarshal_ImageNotFound(buffer: data, offset: 16)
  case 2:
    return unmarshal_ArenaNotFound(buffer: data, offset: 16)
  case 3:
    return unmarshal_SurfaceNotFound(buffer: data, offset: 16)
  case 4:
    return unmarshal_CaptureFailed(buffer: data, offset: 16)
  case 5:
    return unmarshal_OutputNotFound(buffer: data, offset: 16)
  case 6:
    return unmarshal_SettingsWriteFailed(buffer: data, offset: 16)
  case 7:
    return unmarshal_WallpaperUnreadable(buffer: data, offset: 16)
  default:
    return RuntimeError(message: "Unknown exception id: \(exId)")
  }
}
